32	    /// <inheritdoc />
33	    public JsonObject MapFromDataToStorageModel(VectorStoreGenericDataModel<string> dataModel)
34	    {
35	        Verify.NotNull(dataModel);
36	
37	        var storageJsonObject = new JsonObject();
38	
39	        // Loop through all known properties and map each from the data model json to the storage json.
40	        foreach (var property in this._vectorStoreRecordDefinition.Properties)
41	        {
42	            if (property is VectorStoreRecordKeyProperty keyProperty)
43	            {
44	                var storagePropertyName = keyProperty.StoragePropertyName ?? keyProperty.DataModelPropertyName;
45	                storageJsonObject.Add(storagePropertyName, dataModel.Key);
46	            }
47	            else if (property is VectorStoreRecordDataProperty dataProperty)
48	            {
49	                if (dataModel.Data is not null)
50	                {
51	                    var storagePropertyName = dataProperty.StoragePropertyName ?? dataProperty.DataModelPropertyName;
52	                    var serializedJsonNode = JsonSerializer.SerializeToNode(dataModel.Data[dataProperty.DataModelPropertyName]);
53	                    storageJsonObject.Add(storagePropertyName, serializedJsonNode);
54	                }
55	            }
56	            else if (property is VectorStoreRecordVectorProperty vectorProperty)
57	            {
58	                if (dataModel.Vectors is not null)
59	                {
60	                    var storagePropertyName = vectorProperty.StoragePropertyName ?? vectorProperty.DataModelPropertyName;
61	
62	                    var serializedJsonNode = JsonSerializer.SerializeToNode(dataModel.Vectors[vectorProperty.DataModelPropertyName]);
63	                    storageJsonObject.Add(storagePropertyName, serializedJsonNode);
64	                }
65	            }
66	        }
67	
68	        return storageJsonObject;
69	    }
