namespace Microsoft.SemanticKernel.Connectors.Qdrant;

/// <summary>
/// A mapper that maps between the generic semantic kernel data model and the model that the data is stored in in Qdrant.
/// </summary>
internal class QdrantGenericDataModelMapper :
    IVectorStoreRecordMapper<VectorStoreGenericDataModel<ulong>, PointStruct>,
    IVectorStoreRecordMapper<VectorStoreGenericDataModel<Guid>, PointStruct>
{
    /// <summary>A <see cref="VectorStoreRecordDefinition"/> that defines the schema of the data in the database.</summary>
    private readonly VectorStoreRecordDefinition _vectorStoreRecordDefinition;

    /// <summary>A value indicating whether the vectors in the store are named, or whether there is just a single unnamed vector per qdrant point.</summary>
    private readonly bool _hasNamedVectors;

    /// <summary>
    /// Initializes a new instance of the <see cref="QdrantGenericDataModelMapper"/> class.
    /// </summary>
    /// <param name="vectorStoreRecordDefinition">A <see cref="VectorStoreRecordDefinition"/> that defines the schema of the data in the database.</param>
    /// <param name="hasNamedVectors">A value indicating whether the vectors in the store are named, or whether there is just a single unnamed vector per qdrant point.</param>
    public QdrantGenericDataModelMapper(
        VectorStoreRecordDefinition vectorStoreRecordDefinition,
        bool hasNamedVectors)
    {
        Verify.NotNull(vectorStoreRecordDefinition);

        this._vectorStoreRecordDefinition = vectorStoreRecordDefinition;
        this._hasNamedVectors = hasNamedVectors;
    }

    /// <inheritdoc />
    public PointStruct MapFromDataToStorageModel(VectorStoreGenericDataModel<ulong> dataModel)
    {
        return this.MapFromDataToStorageModel(dataModel, new PointId { Num = dataModel.Key });
    }

    /// <inheritdoc />
    public PointStruct MapFromDataToStorageModel(VectorStoreGenericDataModel<Guid> dataModel)
    {
        return this.MapFromDataToStorageModel(dataModel, new PointId { Uuid = dataModel.Key.ToString("D") });
    }

    /// <inheritdoc />
    VectorStoreGenericDataModel<ulong> IVectorStoreRecordMapper<VectorStoreGenericDataModel<ulong>, PointStruct>.MapFromStorageToDataModel(PointStruct storageModel, StorageToDataModelMapperOptions options)
    {
        return this.MapFromStorageToDataModel<ulong>(storageModel, options);
    }

    /// <inheritdoc />
    VectorStoreGenericDataModel<Guid> IVectorStoreRecordMapper<VectorStoreGenericDataModel<Guid>, PointStruct>.MapFromStorageToDataModel(PointStruct storageModel, StorageToDataModelMapperOptions options)
    {
        return this.MapFromStorageToDataModel<Guid>(storageModel, options);
    }

    /// <summary>
    /// Maps from the generic data model to the Qdrant point using the provided point id.
    /// </summary>
    /// <typeparam name="TKey">The type of the key.</typeparam>
    /// <param name="dataModel">The generic data model to map from.</param>
    /// <param name="pointId">The point id to use for the created point.</param>
    /// <returns>The mapped Qdrant point.</returns>
    private PointStruct MapFromDataToStorageModel<TKey>(VectorStoreGenericDataModel<TKey> dataModel, PointId pointId)
        where TKey : notnull
    {
        Verify.NotNull(dataModel);

        // Create point.
        var pointStruct = new PointStruct
        {
            Id = pointId,
            Vectors = new Vectors(),
            Payload = { },
        };

        // Add point payload.
        foreach (var dataProperty in this._vectorStoreRecordDefinition.Properties.OfType<VectorStoreRecordDataProperty>())
        {
            var storagePropertyName = dataProperty.StoragePropertyName ?? dataProperty.DataModelPropertyName;

            // Just skip this property if it's not in the data model.
            if (dataModel.Data.TryGetValue(dataProperty.DataModelPropertyName, out var dataValue))
            {
                pointStruct.Payload.Add(storagePropertyName, ConvertToGrpcFieldValue(dataValue));
            }
        }

        // Add vectors.
        if (this._hasNamedVectors)
        {
            var namedVectors = new NamedVectors();
            foreach (var vectorProperty in this._vectorStoreRecordDefinition.Properties.OfType<VectorStoreRecordVectorProperty>())
            {
                var storagePropertyName = vectorProperty.StoragePropertyName ?? vectorProperty.DataModelPropertyName;

                // Just skip this property if it's not in the data model.
                if (dataModel.Vectors.TryGetValue(vectorProperty.DataModelPropertyName, out var vectorValue))
                {
                    if (vectorValue is not ReadOnlyMemory<float> floatROM)
                    {
                        throw new VectorStoreRecordMappingException($"Vector property '{vectorProperty.DataModelPropertyName}' on provided record of type VectorStoreGenericDataModel must be of type ReadOnlyMemory<float> and not null.");
                    }

                    namedVectors.Vectors.Add(storagePropertyName, floatROM.ToArray());
                }
            }

            pointStruct.Vectors.Vectors_ = namedVectors;
        }
        else
        {
            // We already verified in the constructor via FindProperties that there is exactly one vector property when not using named vectors.
            var vectorProperty = this._vectorStoreRecordDefinition.Properties.OfType<VectorStoreRecordVectorProperty>().First();

            if (!dataModel.Vectors.TryGetValue(vectorProperty.DataModelPropertyName, out var vectorValue) || vectorValue is not ReadOnlyMemory<float> floatROM)
            {
                throw new VectorStoreRecordMappingException($"Vector property '{vectorProperty.DataModelPropertyName}' on provided record of type VectorStoreGenericDataModel must be of type ReadOnlyMemory<float> and not null.");
            }

            pointStruct.Vectors.Vector = floatROM.ToArray();
        }

        return pointStruct;
    }

    /// <summary>
    /// Maps from the Qdrant point to the generic data model.
    /// </summary>
    /// <typeparam name="TKey">The type of the key.</typeparam>
    /// <param name="storageModel">The Qdrant point to map from.</param>
    /// <param name="options">Options to control the mapping behavior.</param>
    /// <returns>The mapped generic data model.</returns>
    private VectorStoreGenericDataModel<TKey> MapFromStorageToDataModel<TKey>(PointStruct storageModel, StorageToDataModelMapperOptions options)
        where TKey : notnull
    {
        Verify.NotNull(storageModel);

